tool_input.new_string:
const counts = ref<{ all: number; rescue: number; draft: number; submitted: number }>({ all: 0, rescue: 0, draft: 0, submitted: 0 })
type CountKey = 'all' | 'rescue' | 'draft' | 'submitted'
const countsLoading = ref<Record<CountKey, boolean>>({ all: true, rescue: true, draft: true, submitted: true })
let countsRequestId = 0

tool_input.old_string:
async function refreshCounts() {
  const requestId = ++countsRequestId
  if (!countsLoaded) countsLoading.value = true
  try {
    const [all, rescue, draft, submitted] = await Promise.all([
      store.countHistory({ kinds: tabKinds.value, status: 'all', complexId: selection.value?.complexId, eventId: selection.value?.eventId }),
      store.countHistory({ kinds: ['rescue'], status: 'all', complexId: selection.value?.complexId }),
      store.countHistory({ kinds: tabKinds.value, status: 'draft', complexId: selection.value?.complexId, eventId: selection.value?.eventId }),
      store.countHistory({ kinds: tabKinds.value, status: 'submitted', complexId: selection.value?.complexId, eventId: selection.value?.eventId }),
    ])
    if (requestId === countsRequestId) counts.value = { all, rescue, draft, submitted }
  } catch { if (requestId === countsRequestId) counts.value = { all: 0, rescue: 0, draft: 0, submitted: 0 } }
  finally { if (requestId === countsRequestId) { countsLoaded = true; countsLoading.value = false } }
}

tool_input.new_string:
function countQueryBase() {
  return { kinds: tabKinds.value, complexId: selection.value?.complexId, eventId: selection.value?.eventId } as const
}
async function loadCount(key: CountKey, requestId: number) {
  countsLoading.value[key] = true
  try {
    let n = 0
    const base = countQueryBase()
    if (key === 'all') n = await store.countHistory({ ...base, status: 'all' })
    else if (key === 'rescue') {
      if (tab.value !== 'mid') n = counts.value.rescue
      else n = await store.countHistory({ kinds: ['rescue'], status: 'all', complexId: selection.value?.complexId })
    } else if (key === 'draft') n = await store.countHistory({ ...base, status: 'draft' })
    else n = await store.countHistory({ ...base, status: 'submitted' })
    if (requestId === countsRequestId) counts.value[key] = n
  } catch {
    if (requestId === countsRequestId) counts.value[key] = 0
  } finally {
    if (requestId === countsRequestId) countsLoading.value[key] = false
  }
}
/** bug6969：分路拉计数，「全部工单」不等救援/归档；汛前汛后不请求 rescue */
function refreshCounts() {
  const requestId = ++countsRequestId
  const keys: CountKey[] = tab.value === 'mid' ? ['all', 'rescue', 'submitted'] : ['all', 'submitted']
  for (const key of keys) void loadCount(key, requestId)
}

